package com.clancoffertracker;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;


@ConfigGroup("clancoffertracker")
public interface ClanCofferTrackerConfig extends Config
{
	@ConfigItem(
			keyName = "enableTracking",
			name = "Enable Deposit Tracking",
			description = "Detect clan coffer deposits"
	)
	default boolean enableTracking()
	{
		return true;
	}



	@ConfigItem(
			keyName = "clanId",
			name = "Clan ID",
			description = "Identifier for your clan's deposit records"
	)
	default String clanId()
	{
		return "";
	}


	@ConfigItem(
			keyName = "discordWebhook",
			name = "Discord Webhook URL",
			description = "Discord webhook for clan coffer deposit notifications",
			secret = true,
			position = 3
	)
	default String discordWebhook()
	{
		return "";
	}


	@ConfigItem(
			keyName = "enableDiscord",
			name = "Enable Discord Reporting",
			description = "Sends player names and coffer deposit amounts to the configured Discord webhook. Only enable this if you agree to share this information with Discord.",
			position = 4
	)
	default boolean enableDiscord()
	{
		return false;
	}



}

package com.clancoffertracker;

import com.google.inject.Provides;
import java.util.Locale;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.Text;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
		name = "Clan Coffer Tracker",
		description = "Tracks clan coffer deposits with optional Discord notifications",
		tags = {"clan", "coffer", "deposits"}
)
public class ClanCofferTrackerPlugin extends Plugin
{
	private static final Logger log =
			LoggerFactory.getLogger(ClanCofferTrackerPlugin.class);

	private static final MediaType JSON =
			MediaType.parse("application/json; charset=utf-8");

	private ExecutorService reportExecutor;

	@Inject
	private ClanCofferTrackerConfig config;

	@Inject
	private OkHttpClient httpClient;

	@Provides
	ClanCofferTrackerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ClanCofferTrackerConfig.class);
	}

	@Override
	protected void startUp()
	{
		reportExecutor = Executors.newSingleThreadExecutor();
	}

	@Override
	protected void shutDown()
	{
		if (reportExecutor != null)
		{
			reportExecutor.shutdownNow();
			reportExecutor = null;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{


		if (!config.enableTracking() || !config.enableDiscord())
		{
			return;
		}

		ChatMessageType type = event.getType();

		if (type != ChatMessageType.CLAN_MESSAGE
				&& type != ChatMessageType.CLAN_GIM_MESSAGE
				&& type != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}

		String message = event.getMessage();

		if (message == null
				|| !message.toLowerCase(Locale.ROOT).contains("coffer"))
		{
			return;
		}

		CofferDepositParser.Deposit deposit =
				CofferDepositParser.parse(message);

		if (deposit == null)
		{
			return;
		}

		String webhook = config.discordWebhook();

		if (webhook == null || webhook.trim().isEmpty())
		{
			return;
		}

		webhook = webhook.trim();

		if (!isDiscordWebhook(webhook))
		{
			log.warn("Discord webhook URL is invalid");
			return;
		}

		log.info("Clan coffer deposit detected: {} GP", deposit.amount);

		sendDiscordNotification(webhook, deposit.player, deposit.amount);
	}

	private void sendDiscordNotification(
			String webhook,
			String player,
			long amount
	)
	{
		ExecutorService executor = reportExecutor;

		if (executor == null || executor.isShutdown())
		{
			return;
		}

		String message = String.format(
				"Clan Coffer Deposit!\nPlayer: %s\nAmount: %,d GP",
				player,
				amount
		);

		String json =
				"{\"content\":\"" + escapeJson(message)
						+ "\",\"allowed_mentions\":{\"parse\":[]}}";

		final String webhookUrl = webhook;

		try
		{
			executor.submit(() -> postDiscord(webhookUrl, json));
		}
		catch (java.util.concurrent.RejectedExecutionException ex)
		{
			log.debug("Discord notification skipped during shutdown");
		}
	}

	private static boolean isDiscordWebhook(String webhook)
	{
		try
		{
			okhttp3.HttpUrl url = okhttp3.HttpUrl.parse(webhook);

			if (url == null)
			{
				return false;
			}

			String host = url.host().toLowerCase(Locale.ROOT);

			return url.isHttps()
					&& (host.equals("discord.com")
					|| host.equals("discordapp.com"))
					&& url.port() == 443
					&& url.username().isEmpty()
					&& url.password().isEmpty()
					&& url.query() == null
					&& url.fragment() == null
					&& url.encodedPath().matches(
					"/api/webhooks/[0-9]+/[^/]+/?"
			);
		}
		catch (Exception ex)
		{
			return false;
		}
	}

	private static String escapeJson(String value)
	{
		StringBuilder escaped = new StringBuilder();

		for (int i = 0; i < value.length(); i++)
		{
			char c = value.charAt(i);

			switch (c)
			{
				case '"':
					escaped.append("\\\"");
					break;
				case '\\':
					escaped.append("\\\\");
					break;
				case '\n':
					escaped.append("\\n");
					break;
				case '\r':
					escaped.append("\\r");
					break;
				case '\t':
					escaped.append("\\t");
					break;
				default:
					if (c < 0x20)
					{
						escaped.append(String.format("\\u%04x", (int) c));
					}
					else
					{
						escaped.append(c);
					}
					break;
			}
		}

		return escaped.toString();
	}

	private void postDiscord(String webhook, String json)
	{
		RequestBody body = RequestBody.create(JSON, json);

		Request request = new Request.Builder()
				.url(webhook)
				.post(body)
				.build();

		// Prevent redirects from forwarding webhook requests.
		OkHttpClient client = httpClient.newBuilder()
				.followRedirects(false)
				.followSslRedirects(false)
				.build();

		try (Response response = client.newCall(request).execute())
		{
			if (response.code() == 204 || response.code() == 200)
			{
				log.info("Discord notification sent successfully");
			}
			else
			{
				log.warn("Discord returned HTTP {}", response.code());
			}
		}
		catch (Exception ex)
		{
			// Do not log exceptions containing secret webhook URLs.
			log.warn("Failed to send Discord notification");
		}
	}
}

package com.clancoffertracker;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class CofferDepositParser
{
    private static final Pattern DEPOSIT_PATTERN =
            Pattern.compile(
                    "^(.+?) has deposited ([\\d,]+) coins? into the coffer\\.$",
                    Pattern.CASE_INSENSITIVE
            );

    private static final Pattern FORMATTED_DEPOSIT_PATTERN =
            Pattern.compile(
                    "^<int_0=(\\d+)>(.+?) has deposited <int_0:spacer> coins? into the coffer\\.$",
                    Pattern.CASE_INSENSITIVE
            );

    public static Deposit parse(String message)
    {
        if (message == null)
        {
            return null;
        }

        String text = message.trim();

        // Handle RuneLite's raw clan coffer announcement.
        Matcher formatted = FORMATTED_DEPOSIT_PATTERN.matcher(text);

        if (formatted.matches())
        {
            try
            {
                long amount = Long.parseLong(formatted.group(1));
                String player = normalizePlayer(formatted.group(2));

                if (player.isEmpty() || amount <= 0)
                {
                    return null;
                }

                return new Deposit(player, amount);
            }
            catch (NumberFormatException ex)
            {
                return null;
            }
        }

        // Handle ordinary messages containing a visible GP amount.
        Matcher matcher = DEPOSIT_PATTERN.matcher(text);

        if (!matcher.matches())
        {
            return null;
        }

        try
        {
            String player = normalizePlayer(matcher.group(1));
            long amount = Long.parseLong(
                    matcher.group(2).replace(",", "")
            );

            if (player.isEmpty() || amount <= 0)
            {
                return null;
            }

            return new Deposit(player, amount);
        }
        catch (NumberFormatException ex)
        {
            return null;
        }
    }

    private static String normalizePlayer(String player)
    {
        return player
                .replace("\u00A0", " ")
                .replace("┬á", " ")
                .trim();
    }

    public static class Deposit
    {
        public final String player;
        public final long amount;

        public Deposit(String player, long amount)
        {
            this.player = player;
            this.amount = amount;
        }
    }
}

package com.clancoffertracker;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class ClanCofferTrackerPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(
				ClanCofferTrackerPlugin.class
		);

		RuneLite.main(args);
	}
}

package com.clancoffertracker;

import org.junit.Test;
import static org.junit.Assert.*;

public class CofferDepositParserTest
{
    @Test
    public void testNoMercyDeposit()
    {
        CofferDepositParser.Deposit deposit =
                CofferDepositParser.parse(
                        "NoMercy has deposited 1,000,000 coins into the coffer."
                );

        assertNotNull(deposit);
        assertEquals("NoMercy", deposit.player);
        assertEquals(1000000L, deposit.amount);
    }

    @Test
    public void testInvalidMessage()
    {
        assertNull(CofferDepositParser.parse(
                "NoMercy has withdrawn 1,000,000 coins."
        ));
    }

    @Test
    public void testZeroDeposit()
    {
        assertNull(CofferDepositParser.parse(
                "NoMercy has deposited 0 coins into the coffer."
        ));
    }


    @Test
    public void testRealClanCofferDeposit()
    {
        String message =
                "<int_0=10000000>Ember\u00A0Ego has deposited "
                        + "<int_0:spacer> coins into the coffer.";

        CofferDepositParser.Deposit deposit =
                CofferDepositParser.parse(message);

        assertNotNull(deposit);
        assertEquals("Ember Ego", deposit.player);
        assertEquals(10000000L, deposit.amount);
    }

}

package com.clancoffertracker;

import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;

public class DiscordWebhookTest
{
    public static void main(String[] args) throws Exception
    {
        // Paste your Discord webhook here temporarily.
        String webhook = System.getenv("DISCORD_WEBHOOK_TEST_URL");

        if (webhook == null || webhook.isEmpty())
        {
            System.out.println("Set DISCORD_WEBHOOK_TEST_URL first.");
            return;
        }

        String json = "{\"content\":\"Clan Coffer Tracker Test!\\nPlayer: TestPlayer\\nAmount: 500,000 GP\"}";

        HttpURLConnection connection =
                (HttpURLConnection) new URL(webhook).openConnection();

        connection.setRequestMethod("POST");
        connection.setRequestProperty(
                "Content-Type", "application/json"
        );
        connection.setConnectTimeout(5000);
        connection.setReadTimeout(5000);
        connection.setDoOutput(true);

        try (OutputStream output = connection.getOutputStream())
        {
            output.write(json.getBytes(StandardCharsets.UTF_8));
        }

        System.out.println(
                "Discord HTTP Status: " + connection.getResponseCode()
        );

        connection.disconnect();
    }
}
